proc  sdf_hp ( theta ) ;

       local psi1, psi2, m ;

    psi1=theta[1];
    psi2=theta[2];
    m=sin(psi1)+f*cos(psi1)*sin(psi2)+fno*cos(psi1)*cos(psi2) ;

    retp( rr.*m ) ;

endp; 

proc  sdf_h2p ( theta ) ;

	local   ups1, ups2,  mu, u, m ;

    ups1=theta[1];
    ups2=theta[2];
    mu=theta[3:4]; 
    u=ff-mu';
    m=sin(ups1)+u[.,1]*cos(ups1)*sin(ups2)+u[.,2]*cos(ups1)*cos(ups2) ;

	   retp( (rr.*m) ~ u  ) ;
endp; 


proc  sdf_h ( theta ) ;

	local   h_r_t, h_f_t ;

    h_r_t= r.*(1-ff*theta) ; 
    h_f_t= f.*(1-ff*theta) ;

	   retp( h_r_t~h_f_t  ) ;
endp; 


proc  sdf_h2 ( theta ) ;

	local  tau, mu, 
            u, h_r_t, h_f_t, h_u_t ;

    tau=theta[1:kk];
    mu=theta[kk+1:2*kk];

    u=ff-mu';
    h_r_t= r.*(1-u*tau) ; 
    h_f_t= f.*(1-u*tau) ;
    h_u_t= u ;

  	   retp(h_r_t~h_f_t~h_u_t );
endp;


proc  reg_h ( theta ) ;


	local   lamno, beta, mu,  bb ;

    lamno=theta[1:kno];
    beta=theta[kno+1:kno+kk*n];
    mu=theta[kno+kk*n+1:rows(theta)];

    bb=reshape(beta,kk,n)';

	retp( ((ones(t,1)~ff) *~ (r-f*bb[.,1:k]'-(fno-mu[k+1:rows(mu)]'+lamno')*bb[.,k+1:cols(bb)]')) ~ (ff-mu') ) ;

endp; 



